CG3_INLINE void holeFillingFileOff(const std::string& input, const std::string& output)
{
    std::ifstream sinput(input);
    Polyhedron poly;
    if ( !sinput || !(sinput >> poly) || poly.empty() ) {
        std::cerr << "Not a valid off file." << std::endl;
        assert(0);
    }

    holeFilling(poly);

    std::ofstream out(output);
    out.precision(17);
    out << poly << std::endl;
}

